sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float radius;
uniform float amount;
uniform float edgeLow;
uniform float edgeHigh;
uniform float method;
uniform float darken;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float3 sum = float3(0.0);
    float ws = 0.0;
    for (int k = 0; k < 2; k++) {
        float rr = radius * (float(k) + 1.0) / 2.0;
        for (int i = 0; i < 8; i++) {
            float a = float(i) * 0.7853982;
            float4 s4 = tex(coord + float2(cos(a), sin(a)) * rr);
            float w = pow(s4.a, 4.0);
            sum += unp(s4) * w;
            ws += w;
        }
    }
    float3 inner = ws > 0.0001 ? sum / ws : s;
    float edge = smoothstep(0.0, edgeLow + 0.001, c.a) * (1.0 - smoothstep(edgeHigh - 0.2, edgeHigh, c.a));
    float3 o = method < 0.5 ? mix(s, inner, edge * amount) : mix(s, float3(luma(s)), edge * amount);
    o *= 1.0 - darken * edge * amount;
    return fin(c, float4(saturate(o) * c.a, c.a), opacity);
}
